    this.cache=new Map();
    this.ttl=ttlMs;
    this.startCleaner();
  }
  onMessage(ctx, msg) {
    const k=msg.key; const id=msg.id;
    const last=this.cache.get(k);
    if(last != null && id<=last) return false;
    this.cache.set(k,id);
    return true;
